(30166, 'Romans 16:11', 'Romans', 16, 11, 'زما وطندار هیرودیون او نرکیسوس د کورنۍ ایماندارانو ته سلامونه ووایئ.', 'زما وطندار هیرودیون او نرکیسوس د کورنی ایماندارانو ته سلامونه ووایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30167, 'Romans 16:12', 'Romans', 16, 12, 'تریفینا او تریفوسا ته چې د څښتن خدمت کوي او ګرانې پرسیس ته چې د څښتن دپاره یې ډېر زحمت ویستلی دی، سلامونه ووایئ.', 'تریفینا او تریفوسا ته چې د چشتن خدمت کوی او ګرانې پرسیس ته چې د چشتن دپاره یې دېر زحمت ویستلی دی، سلامونه ووایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30168, 'Romans 16:13', 'Romans', 16, 13, 'روفس ته چې د څښتن له خوا غوره شوی دی او د هغه مور ته چې ماته هم لکه د مور په شان ده، سلامونه ووایئ.', 'روفس ته چې د چشتن له خوا غوره شوی دی او د هغه مور ته چې ماته هم لکه د مور په شان ده، سلامونه ووایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30169, 'Romans 16:14', 'Romans', 16, 14, 'اسونکریتوس، فلیګون، هرمیس، پتروباس، هرماس او نورو خویندو او ورونو ته چې د هغوی سره دي، سلامونه ووایئ.', 'اسونکریتوس، فلیګون، هرمیس، پتروباس، هرماس او نورو خویندو او ورونو ته چې د هغوی سره دی، سلامونه ووایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30170, 'Romans 16:15', 'Romans', 16, 15, 'فیلولوګاس، جولیه، نیریاس او د هغه خور او اولیمپیاس او ټولو ایماندارانو ته چې د هغوی سره دي، سلامونه ووایئ.', 'فیلولوګاس، جولیه، نیریاس او د هغه خور او اولیمپیاس او تولو ایماندارانو ته چې د هغوی سره دی، سلامونه ووایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30171, 'Romans 16:16', 'Romans', 16, 16, 'یو بل ته سلام ووایئ او په پاکه مینه یو بل ښکل کړئ. د مسیح ټولې کلیساګانې تاسو ته سلام وایي. وروستنۍ لارښوونې', 'یو بل ته سلام ووایی او په پاکه مینه یو بل شکل کری. د مسیح تولې کلیساګانې تاسو ته سلام وایی. وروستنی لارشوونې', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30172, 'Romans 16:17', 'Romans', 16, 17, 'ای خویندو او ورونو! زه ستاسو نه غوښتنه کوم چې هغو خلکو ته مو پام وي چې بې‌اتفاقي رامنځته کوي او نور بې‌لارې کوي او د هغه تعلیم په خلاف دي چې تاسو حاصل کړی دی. د هغوی څخه ځان لېرې وساتئ.', 'ای خویندو او ورونو! زه ستاسو نه غوشتنه کوم چې هغو خلکو ته مو پام وی چې بې‌اتفاقی رامنجته کوی او نور بې‌لارې کوی او د هغه تعلیم په خلاف دی چې تاسو حاصل کری دی. د هغوی چخه جان لېرې وساتی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30173, 'Romans 16:18', 'Romans', 16, 18, 'ځکه چې داسې خلک زمونږ د څښتن مسیح خدمت نه کوي، بلکې د خپلې خېټې دپاره کار کوي او په خوږو خبرو او غوړه مالۍ سره ساده خلک غولوي.', 'جکه چې داسې خلک زمونز د چشتن مسیح خدمت نه کوی، بلکې د خپلې خېتې دپاره کار کوی او په خوزو خبرو او غوره مالی سره ساده خلک غولوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30174, 'Romans 16:19', 'Romans', 16, 19, 'ځکه چې د څښتن څخه ستاسو اطاعت کول ټولو خلکو ته معلوم دي او له همدې امله زه ستاسو په خاطر خوشحاله یم. خو زه غواړم چې تاسو په ښه کار کې هوښیار اوسئ او په بد کار کې بې‌ګناه اوسئ.', 'جکه چې د چشتن چخه ستاسو اطاعت کول تولو خلکو ته معلوم دی او له همدې امله زه ستاسو په خاطر خوشحاله یم. خو زه غوارم چې تاسو په شه کار کې هوشیار اوسی او په بد کار کې بې‌ګناه اوسی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30175, 'Romans 16:20', 'Romans', 16, 20, 'خدای چې د سلامتۍ سرچینه ده، هغه به زر شیطان ستاسو د پښو لاندې ټوټې ټوټې کړي. په تاسو باندې دې زمونږ د څښتن عیسی مسیح فضل وي.', 'خدای چې د سلامتی سرچینه ده، هغه به زر شیطان ستاسو د پشو لاندې توتې توتې کری. په تاسو باندې دې زمونز د چشتن عیسی مسیح فضل وی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30176, 'Romans 16:21', 'Romans', 16, 21, 'زما همکار تیموتاوس او همدارنګه زما وطنداران لوسیوس او یاسون او سوسیپاتوس هم تاسو ته سلامونه وایي.', 'زما همکار تیموتاوس او همدارنګه زما وطنداران لوسیوس او یاسون او سوسیپاتوس هم تاسو ته سلامونه وایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30177, 'Romans 16:22', 'Romans', 16, 22, 'زه ترتیوس د پولوس منشي د دې لیک لیکونکی هم تاسو ته د څښتن په نوم سلامونه وایم.', 'زه ترتیوس د پولوس منشی د دې لیک لیکونکی هم تاسو ته د چشتن په نوم سلامونه وایم.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30178, 'Romans 16:23', 'Romans', 16, 23, 'ګایوس چې زما او د هغه په کور کې د ټولې کلیسا کوربه دی، تاسو ته سلامونه وایي او د ښار خزانه دار اراستوس او زمونږ ورور کوارتس هم تاسو ته سلامونه وایي.', 'ګایوس چې زما او د هغه په کور کې د تولې کلیسا کوربه دی، تاسو ته سلامونه وایی او د شار خزانه دار اراستوس او زمونز ورور کوارتس هم تاسو ته سلامونه وایی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_23.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30179, 'Romans 16:24', 'Romans', 16, 24, '[زمونږ د څښتن عیسی مسیح فضل دې په تاسو ټولو باندې وي. امین.] د پولوس اخرنۍ دعا', '[زمونز د چشتن عیسی مسیح فضل دې په تاسو تولو باندې وی. امین.] د پولوس اخرنی دعا', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_24.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30180, 'Romans 16:25', 'Romans', 16, 25, 'اوس دې خدای ته جلال وي چې کولای شي تاسو په ایمان کې د عیسی مسیح د زیري له مخې چې زه یې اعلانوم او د هغه راز د څرګندولو له مخې چې د پېړیو پېړیو راهیسې پټ پاتې ؤ، قوي کړي.', 'اوس دې خدای ته جلال وی چې کولای شی تاسو په ایمان کې د عیسی مسیح د زیری له مخې چې زه یې اعلانوم او د هغه راز د چرګندولو له مخې چې د پېریو پېریو راهیسې پت پاتې و، قوی کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30181, 'Romans 16:26', 'Romans', 16, 26, 'اوس دا حقیقت د پیغمبرانو د لیکنو په وسیله څرګند شوی دی او د ابدي خدای د حکم له مخې د دنیا ټولو قومونو ته ښکاره شوی دی، ترڅو هغوی ایمان راوړي او د هغه اطاعت وکړي.', 'اوس دا حقیقت د پیغمبرانو د لیکنو په وسیله چرګند شوی دی او د ابدی خدای د حکم له مخې د دنیا تولو قومونو ته شکاره شوی دی، ترچو هغوی ایمان راوری او د هغه اطاعت وکری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_26.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30182, 'Romans 16:27', 'Romans', 16, 27, 'هغه واحد او یوازېني خدای ته دې چې په هرڅه پوهیږي د عیسی مسیح په وسیله تل ترتله جلال وي. امین.', 'هغه واحد او یوازېنی خدای ته دې چې په هرچه پوهیزی د عیسی مسیح په وسیله تل ترتله جلال وی. امین.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Romans_16_27.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237835, 1761237835),
(30183, 'James 1:1', 'James', 1, 1, 'د خدای او د څښتن عیسی مسیح د خدمتګار یعقوب له خوا دې د اسراییلو دولس قبیلو ته چې په ټوله نړۍ کې خواره واره شوي دي، سلام وي. ایمان او حکمت', 'د خدای او د چشتن عیسی مسیح د خدمتګار یعقوب له خوا دې د اسراییلو دولس قبیلو ته چې په توله نری کې خواره واره شوی دی، سلام وی. ایمان او حکمت', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30184, 'James 1:2', 'James', 1, 2, 'ای زما خویندو او ورونو! هرکله چې تاسو د ډول ډول ازمېښتونو سره مخامخ کېږئ نو هغه یوه خوشحالي وګڼئ،', 'ای زما خویندو او ورونو! هرکله چې تاسو د دول دول ازمېشتونو سره مخامخ کېزی نو هغه یوه خوشحالی وګنی،', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30185, 'James 1:3', 'James', 1, 3, 'ځکه تاسو پوهېږئ چې دا ستاسو د ایمان په ازمېښت کې ستاسو صبر او زغم زیاتوي.', 'جکه تاسو پوهېزی چې دا ستاسو د ایمان په ازمېشت کې ستاسو صبر او زغم زیاتوی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30186, 'James 1:4', 'James', 1, 4, 'کله چې ستاسو صبر او زغم نور هم زیات شي، نو تاسو به کامل او بې‌عیبه انسانان شئ او د هېڅ شي کمی به په تاسو کې نه وي.', 'کله چې ستاسو صبر او زغم نور هم زیات شی، نو تاسو به کامل او بې‌عیبه انسانان شی او د هېچ شی کمی به په تاسو کې نه وی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30187, 'James 1:5', 'James', 1, 5, 'خو که په تاسو کې په چا کې د حکمت کمی وي، نو هغه دې د خدای څخه وغواړي چې هغه یې د سخاوت له مخې او بې له دې چې څوک ملامته کړي هرچا ته ورکوي، نو هغه ته به هم ورکړل شي.', 'خو که په تاسو کې په چا کې د حکمت کمی وی، نو هغه دې د خدای چخه وغواری چې هغه یې د سخاوت له مخې او بې له دې چې چوک ملامته کری هرچا ته ورکوی، نو هغه ته به هم ورکرل شی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30188, 'James 1:6', 'James', 1, 6, 'خو کله چې څوک کوم شی غواړي، نو هغه دې د ایمان سره وغواړي او هېڅ شک دې نه کوي، ځکه چې شک کوونکی د بحر د هغو څپو په شان دی چې د باد په وسیله اخوا دې خوا غورځول کیږي.', 'خو کله چې چوک کوم شی غواری، نو هغه دې د ایمان سره وغواری او هېچ شک دې نه کوی، جکه چې شک کوونکی د بحر د هغو چپو په شان دی چې د باد په وسیله اخوا دې خوا غورجول کیزی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
