(30191, 'James 1:9', 'James', 1, 9, 'غریب ورور دې د خدای په وړاندې په خپلې سرلوړۍ باندې ویاړ وکړي', 'غریب ورور دې د خدای په وراندې په خپلې سرلوری باندې ویار وکری', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30192, 'James 1:10', 'James', 1, 10, 'او همدارنګه شتمن ورور دې په خپلې عاجزۍ باندې چې د خدای له خوا ده ویاړ وکړي، ځکه چې هغه به د واښو د ګل په شان له منځه لاړ شي.', 'او همدارنګه شتمن ورور دې په خپلې عاجزی باندې چې د خدای له خوا ده ویار وکری، جکه چې هغه به د واشو د ګل په شان له منجه لار شی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30193, 'James 1:11', 'James', 1, 11, 'ځکه کله چې لمر د خپلې سوځوونکې ګرمۍ سره راوخېژي نو واښه وچ کړي، ګلان یې ورژیږي او ښایست یې له منځه لاړ شي. نو همداسې به شتمن سړی هم د خپل کاروبار سره له منځه لاړ شي. ازمېښتونه او وسوسې', 'جکه کله چې لمر د خپلې سوجوونکې ګرمی سره راوخېژی نو واشه وچ کری، ګلان یې ورژیزی او شایست یې له منجه لار شی. نو همداسې به شتمن سری هم د خپل کاروبار سره له منجه لار شی. ازمېشتونه او وسوسې', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30194, 'James 1:12', 'James', 1, 12, 'بختور دی هغه څوک چې د ازمېښت په وخت کې ټینګ پاتې شي، ځکه کله چې هغه د داسې ازمېښت څخه بریالی تېر شي، نو د ژوندون تاج به چې خدای د هغو خلکو سره چې ورباندې ګران دی وعده کړې ده، تر‌لاسه کړي.', 'بختور دی هغه چوک چې د ازمېشت په وخت کې تینګ پاتې شی، جکه کله چې هغه د داسې ازمېشت چخه بریالی تېر شی، نو د ژوندون تاج به چې خدای د هغو خلکو سره چې ورباندې ګران دی وعده کرې ده، تر‌لاسه کری.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30195, 'James 1:13', 'James', 1, 13, 'څوک چې وسوسه کیږي، نو هغه باید دا ونه وایي: «خدای زه وسوسه کړی یم،» ځکه چې خدای د هېڅ ډول بدۍ په وسیله نه وسوسه کیږي او نه هم څوک وسوسه کوي.', 'چوک چې وسوسه کیزی، نو هغه باید دا ونه وایی: «خدای زه وسوسه کری یم،» جکه چې خدای د هېچ دول بدی په وسیله نه وسوسه کیزی او نه هم چوک وسوسه کوی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30196, 'James 1:14', 'James', 1, 14, 'خو یو کس هغه وخت وسوسه کیږي چې کله هغه د خپلو نفساني غوښتنو په وسیله وهڅول شي او په دام کې راونیول شي.', 'خو یو کس هغه وخت وسوسه کیزی چې کله هغه د خپلو نفسانی غوشتنو په وسیله وهچول شی او په دام کې راونیول شی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
(30197, 'James 1:15', 'James', 1, 15, 'بیا د هغه نفساني غوښتنې د ګناه د راپیدا کېدلو سبب کیږي او کله چې ګناه خپل وروستي حد ته ورسیږي، نو د مرګ سبب ګرځي.', 'بیا د هغه نفسانی غوشتنې د ګناه د راپیدا کېدلو سبب کیزی او کله چې ګناه خپل وروستی حد ته ورسیزی، نو د مرګ سبب ګرجی.', 'NT', 'afghan2023', 'afghan', '', '', 1761237835, 1761237835),
